const boardLabels={main:'Main Signal Board',speculation:'Dark Speculation Board','epstein-alive':'Epstein Alive / Sighting Board'};
const validBoards=new Set(Object.keys(boardLabels));
function cleanText(v,m=1000){return String(v||'').replace(/<[^>]*>/g,'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,m)}
function normalizeBoard(v='main'){const b=cleanText(v,80).toLowerCase().replace(/[^a-z0-9-]/g,'-');return validBoards.has(b)?b:'main'}
function inferBoardFromPost(p={}){return normalizeBoard(p.board||p.category||'main')}
function json(d,status=200){return new Response(JSON.stringify(d,null,2),{status,headers:jsonHeaders})}
async function readBody(request){const type=request.headers.get('content-type')||'';if(type.includes('application/json'))return request.json().catch(()=>({}));const form=await request.formData().catch(()=>null);return form?Object.fromEntries(form.entries()):{}}
function makeId(){return `signal-${Date.now()}-${Math.random().toString(36).slice(2,10)}`}
function hashId(text){let n=0;for(const ch of String(text||''))n=(n*31+ch.charCodeAt(0))>>>0;return 'subscriber-'+n.toString(36)}
function safePost(p={}){const board=normalizeBoard(p.board||inferBoardFromPost(p));return{id:cleanText(p.id||makeId(),120),board,title:cleanText(p.title||'Untitled Signal',140),body:cleanText(p.body||p.message||'',1800),category:cleanText(p.category||'Signal',80),name:cleanText(p.name||'Anonymous',80),sourceUrl:cleanText(p.sourceUrl||p.source||'',500),createdAt:cleanText(p.createdAt||new Date().toISOString(),80),approvedAt:cleanText(p.approvedAt||p.createdAt||new Date().toISOString(),80),status:cleanText(p.status||'live',40)}}
function sortPosts(posts=[]){return posts.slice().sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')))}
function boardCounts(posts=[]){return posts.reduce((a,p)=>{const b=normalizeBoard(p.board);a[b]=(a[b]||0)+1;return a},{main:0,speculation:0,'epstein-alive':0})}
function isSyntheticForumPost(post){const blob=[post&&post.id,post&&post.title,post&&post.body,post&&post.category,post&&post.name,post&&post.status].map(v=>String(v||'').toLowerCase()).join(' ');return /synthetic|smoke test|health check|demo post|fixture|qa post|seed post|system check|generated check/.test(blob)}
function publicForumPosts(posts=[]){return sortPosts((posts||[]).map(safePost).filter(p=>p.status==='live'&&!isSyntheticForumPost(p)))}
function filterPostsByBoard(posts=[],board='main'){const b=normalizeBoard(board);return posts.filter(p=>normalizeBoard(p.board)===b)}
async function getForumIndex(env){if(!env.FORUM_POSTS)return[];try{const raw=await env.FORUM_POSTS.get('posts:index');const arr=JSON.parse(raw||'[]');return Array.isArray(arr)?sortPosts(arr.map(safePost)):[]}catch{return[]}}
async function saveForumIndex(env,posts=[]){if(!env.FORUM_POSTS)return false;try{const cleaned=sortPosts(posts.map(safePost)).slice(0,1000);await env.FORUM_POSTS.put('posts:index',JSON.stringify(cleaned),{metadata:{updatedAt:new Date().toISOString(),count:cleaned.length,boardCounts:boardCounts(cleaned),storage:'Cloudflare KV FORUM_POSTS'}});return true}catch{return false}}
async function forumExport(env,board='all'){const stored=await getForumIndex(env);const pub=publicForumPosts(stored);const b=board==='all'?'all':normalizeBoard(board);const posts=b==='all'?pub:filterPostsByBoard(pub,b);return{ok:true,persistent:true,source:'Cloudflare KV FORUM_POSTS',generatedAt:new Date().toISOString(),board:b,boardLabel:b==='all'?'All Boards':boardLabels[b],boardCounts:boardCounts(pub),count:posts.length,syntheticHidden:Math.max(0,stored.length-pub.length),posts:posts.slice(0,60)}}
async function handleForumHealth(env){const stored=await getForumIndex(env);const pub=publicForumPosts(stored);return json({ok:true,worker:workerName,backend:'src/worker.js',assetBinding:Boolean(env.ASSETS),forumPostsBinding:env.FORUM_POSTS?'connected':'missing',bindingHealthy:Boolean(env.FORUM_POSTS),kvBindingName:'FORUM_POSTS',expectedKvNamespaceTitle:'matrixreprogrammed-forum-posts',expectedKvNamespaceId:'99996d87016d4285a833707cbda5232f',persistence:'Cloudflare KV FORUM_POSTS: posts:index plus durable post:* records,board-aware filtering active',indexSelfHealing:true,indexCount:stored.length,storedPostCount:stored.length,publicPostCount:pub.length,syntheticHidden:Math.max(0,stored.length-pub.length),boardAware:true,boardLabels,boardCounts:boardCounts(pub),hardBoardRoutes:Object.keys(hardBoardRouteMap),deployedFrom:'GitHub main',updatedAt})}
async function handleForumFeed(request,env,forcedBoard=''){const url=new URL(request.url);return json(await forumExport(env,cleanText(forcedBoard||url.searchParams.get('board')||'main',80)))}
async function handleForumPostsJson(request,env,forcedBoard=''){const url=new URL(request.url);return json(await forumExport(env,cleanText(forcedBoard||url.searchParams.get('board')||'all',80)))}
async function handleSubmitForumPost(request,env,forcedBoard=''){const body=await readBody(request);if(body.website)return json({ok:false,error:'Spam trap triggered'},400);const title=cleanText(body.title,140),message=cleanText(body.body||body.message,1800);if(title.length<3||message.length<10)return json({ok:false,error:'Signal needs a title and a useful body.'},400);const board=normalizeBoard(forcedBoard||body.board||'main');const post=safePost({id:makeId(),board,title,body:message,category:body.category||'Signal',name:body.name||'Anonymous',sourceUrl:body.sourceUrl||body.source||'',status:'live'});const posts=await getForumIndex(env);posts.unshift(post);const saved=await saveForumIndex(env,posts);if(env.FORUM_POSTS){try{await env.FORUM_POSTS.put(`post:${post.id}`,JSON.stringify(post),{metadata:{createdAt:post.createdAt,title:post.title,status:post.status,board}})}catch{}}return json({ok:true,persistent:true,saved,storage:'Cloudflare KV FORUM_POSTS',board,boardLabel:boardLabels[board],post})}
async function handleReportForumPost(request,env,forcedBoard=''){const body=await readBody(request);const board=normalizeBoard(forcedBoard||body.board||'main');const report={id:makeId(),board,postId:cleanText(body.id||body.postId,120),reason:cleanText(body.reason||'Reported by reader',1000),createdAt:new Date().toISOString()};if(env.FORUM_POSTS){try{await env.FORUM_POSTS.put(`report:${report.id}`,JSON.stringify(report),{metadata:{board,postId:report.postId}})}catch{}}return json({ok:true,persistent:true,reportId:report.id,board})}
async function handleNewsletterSignup(request,env){const body=await readBody(request);const email=cleanText(body.email||'',240).toLowerCase();const name=cleanText(body.name||'',120);if(!email||!email.includes('@'))return json({ok:false,persistent:false,error:'Valid email required'},400);const id=hashId(email);const subscriber={id,email,name,status:'subscribed',source:cleanText(body.source||'newsletter',120),tags:cleanText(body.tags||'',200),consent:cleanText(body.consent||'',80),createdAt:new Date().toISOString()};let saved=false;if(env.FORUM_POSTS){try{const raw=await env.FORUM_POSTS.get('newsletter:index');const index=JSON.parse(raw||'[]');const arr=Array.isArray(index)?index.filter(x=>x&&x.id!==id):[];arr.unshift(subscriber);await env.FORUM_POSTS.put('newsletter:index',JSON.stringify(arr.slice(0,10000)),{metadata:{updatedAt:new Date().toISOString(),count:arr.length,storage:'Cloudflare KV FORUM_POSTS'}});await env.FORUM_POSTS.put(`newsletter:subscriber:${id}`,JSON.stringify(subscriber),{metadata:{email,status:'subscribed'}});saved=true}catch{saved=false}}return json({ok:true,persistent:true,saved,subscriberId:id,subscriber,status:'subscribed',storage:'Cloudflare KV FORUM_POSTS',message:'Saved. Weekly Signal Drop enabled.'})}
