async function handleNewsletterSubscribers(request,env){let subscribers=[];if(env&&env.FORUM_POSTS){try{const raw=await env.FORUM_POSTS.get('newsletter:index');const arr=JSON.parse(raw||'[]');subscribers=Array.isArray(arr)?arr:[]}catch{subscribers=[]}}return json({ok:true,count:subscribers.length,subscribers})}
async function handleNewsletterSendWeekly(request,env){const health=await handleNewsletterHealth(env);return json({ok:true,mode:'preview-only',storage:'Cloudflare KV FORUM_POSTS',digest:'/downloads/weekly-newsletter-latest.json',subscribers:0})}
