function isHostileProbePath(pathname=''){return /\/(?:wp-admin|wp-login|xmlrpc\.php|\.env|vendor\/phpunit|cgi-bin|boaform|phpmyadmin|adminer|\.git|config\.php|setup\.php|shell|password|owa|autodiscover)/i.test(pathname)||/\.(?:php|asp|aspx|jsp|cgi)$/i.test(pathname)}
function cacheHeadersForPath(pathname=''){const p=String(pathname||'').toLowerCase();if(/\.(?:css|js|mjs|png|jpg|jpeg|webp|gif|svg|ico|woff2?|mp4|webm)$/.test(p))return'public, max-age=31536000, immutable';if(/\.(?:pdf|json|xml|txt|md)$/.test(p)||p.startsWith('/downloads/')||p.startsWith('/feeds/'))return'public, max-age=3600, stale-while-revalidate=86400';if(/\.html$/.test(p)||!p.includes('.'))return'public, max-age=300, stale-while-revalidate=3600';return'public, max-age=600, stale-while-revalidate=3600'}
