function safeNotConfigured(name,extra={}){return json({ok:false,configured:false,error:String(name||'service')+' not configured',...extra},200)}
async function handleIntroVoice(){return safeNotConfigured('ELEVENLABS_API_KEY',{fallback:'browser speechSynthesis'})}
